      job.logs.push(`Error: ${job.error}`);
    }
  })();
};

function assetSummary(asset: { id: string; content: string; metadata: { assetPurpose: string } }, kind: string, hosted: boolean, scores: Record<string, EvaluationResult> = {}) {
  const file = basename(asset.content);
  const result = scores[asset.id];
  const motion = result?.typesafe?.visual?.motion;
  return {
    id: asset.id, purpose: asset.metadata.assetPurpose, path: hosted ? file : asset.content, url: `/api/assets/${kind}/${encodeURIComponent(file)}`,
    ...(result === undefined ? {} : { score: result.overall }),
    ...(result?.typesafe ? { evidence: result.typesafe.evidence } : {}),
    ...(motion ? { motion: { style: motion.style.choice, expected: motion.style.expected, seamless: motion.seamless, calm: motion.calm.score / (Object.keys(motion.calm.legend).length - 1) } } : {}),
    ...(result?.improvements.length ? { improvements: result.improvements } : {}),
  };
}

/** Record which streamed candidates ended the run holding an archive cell. */
function markCells(job: GenerationJob, candidates: Array<{ path: string; cell?: string }>) {
  for (const c of candidates) {
    if (!c.cell) continue;
    const url = `/api/assets/images/${encodeURIComponent(basename(c.path))}`;
    const streamed = job.candidates.find(s => s.url === url);
    if (streamed) streamed.cell = c.cell;
  }
}

